def count_target_submatrices(matrix, target):
    from collections import defaultdict
    if not matrix or not matrix[0]:
        return 0
    rows = len(matrix)
    cols = len(matrix[0])
    row_prefix = [[0] * (cols + 1) for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            row_prefix[r][c + 1] = row_prefix[r][c] + matrix[r][c]
    count = 0
    for c1 in range(cols):
        for c2 in range(c1, cols):
            prefix_counts = defaultdict(int)
            prefix_counts[0] = 1
            running = 0
            for r in range(rows):
                strip = row_prefix[r][c2 + 1] - row_prefix[r][c1]
                running += strip
                count += prefix_counts[running - target]
                prefix_counts[running] += 1
    return count
